import csv, os
D = '/home/user/learning_tokens/kb/structs/dinari'
os.makedirs(D, exist_ok=True)

def w(name, head, rows):
    with open(os.path.join(D, name), 'w', encoding='utf-8', newline='') as f:
        c = csv.writer(f); c.writerow(head); c.writerows(rows)
    print(name, len(rows))

